import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf;
    static int pos;

    static String next() {
        while (buf[pos] <= ' ') pos++;
        int start = pos;
        while (pos < buf.length && buf[pos] > ' ') pos++;
        return new String(buf, start, pos - start);
    }

    static long nextLong() {
        while (buf[pos] <= ' ') pos++;
        boolean neg = buf[pos] == '-';
        if (neg) pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] > ' ') r = r * 10 + (buf[pos++] - '0');
        return neg ? -r : r;
    }

    static int nextInt() {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        int n = nextInt();
        int[] a = new int[n];
        int v = 0;
        for (int i = 0; i < n; i++) {
            a[i] = nextInt();
            v = Math.max(v, a[i]);
        }
        int[] ordered = a.clone();
        Arrays.sort(ordered);
        long[] prefix = new long[n + 1];
        for (int i = 0; i < n; i++) prefix[i + 1] = prefix[i] + ordered[i];
        int[] bit = new int[v + 1]; // Fenwick tree over times of orders 0..i
        long answer = 0;
        for (int i = 0; i < n; i++) {
            int value = a[i];
            for (int x = value; x <= v; x += x & -x) bit[x]++;
            long less = 0;
            for (int x = value - 1; x > 0; x -= x & -x) less += bit[x];
            // hours spent in the first value-1 full rounds: sum of min(T[j], value-1)
            int lo = 0, hi = n;
            while (lo < hi) {
                int mid = (lo + hi) >>> 1;
                if (ordered[mid] < value) lo = mid + 1;
                else hi = mid;
            }
            long before = prefix[lo] + (long) (n - lo) * (value - 1);
            // last round: orders j <= i with T[j] >= value
            answer += before + i + 1 - less;
        }
        System.out.println(answer % 1000000000L);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
	"sort"
	"strconv"
)

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Buffer(make([]byte, 1<<20), 1<<20)
	sc.Split(bufio.ScanWords)
	next := func() int {
		sc.Scan()
		v, _ := strconv.Atoi(sc.Text())
		return v
	}
	n := next()
	a := make([]int, n)
	v := 0
	for i := range a {
		a[i] = next()
		v = max(v, a[i])
	}
	ordered := append([]int(nil), a...)
	sort.Ints(ordered)
	prefix := make([]int, n+1)
	for i, x := range ordered {
		prefix[i+1] = prefix[i] + x
	}
	bit := make([]int, v+1) // Fenwick tree over times of orders 0..i
	answer := 0
	for i, value := range a {
		for x := value; x <= v; x += x & -x {
			bit[x]++
		}
		less := 0
		for x := value - 1; x > 0; x -= x & -x {
			less += bit[x]
		}
		// hours spent in the first value-1 full rounds: sum of min(T[j], value-1)
		split := sort.SearchInts(ordered, value)
		before := prefix[split] + (n-split)*(value-1)
		// last round: orders j <= i with T[j] >= value
		answer += before + i + 1 - less
	}
	fmt.Println(answer % 1000000000)
}
